    // i=1: a vs a? (at i+2=3 which is a) -> would be equal across boundary; not ok.
    //
    // Instead choose period 4: "aabb aabb..."
    // Then for offsets 0..3:
    // 0: a vs b
    // 1: a vs b
    // 2: b vs a
    // 3: b vs a
    //
    // So s[i] != s[i+2] always holds.

    let nn: u8 = n as u8;
    let mut v: Vec<char> = Vec::new();
